# Generated by build.py from recipe.yml for recipe pop3-refuse-a-second-session. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'report.eml'), "From: shop@example.com`nTo: ann@example.com`nSubject: Monthly report`n`nOrders taken this month: 1,204.`nOrders shipped this month: 1,187.`nOrders returned this month: 31.`nOrders still waiting for stock: 17.`nOrders cancelled by the customer: 9.`nThe busiest day was the 14th, with 92 orders.`nThe quietest day was the 3rd, with 11 orders.`nThe warehouse in the north shipped 702 orders.`nThe warehouse in the south shipped 485 orders.`nThe average order was worth 38.20.`nThe largest order was worth 912.00.`nNext month's report follows on the first working day.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'two-clients.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Two mail clients on Ann's maildrop at once. The first downloads message 1 slowly, so its`n# session stays open; once the server has opened the maildrop for it, the second logs in.`n# Usage: sh two-clients.sh <pop3 port>`nurl=`"pop3://127.0.0.1:`$1`"`nopened=`$(grep -c `"Maildrop opened`" surl.log)`ncurl -sS --limit-rate 100 -u ann@example.com:annpass -o first.eml `"`$url/1`" &`nfirst=`$!`n# Wait, at most ten seconds, until the server's log shows the first session's maildrop opened.`nn=0`nwhile [ `"`$(grep -c `"Maildrop opened`" surl.log)`" -le `"`$opened`" ] && [ `$n -lt 50 ]; do sleep 0.2; n=`$((n + 1)); done`ncurl -v -sS -u ann@example.com:annpass `"`$url/`" 2> second.log`necho `"second: exit `$?`"`ngrep -E `"^< -ERR|^curl:`" second.log | tr -d '\r'`nwait `$first`necho `"first: exit `$?`"`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--mail-domain', 'example.com', '--mailbox', 'shop@example.com:shoppass', '--mailbox', 'ann@example.com:annpass', 'smtp://127.0.0.1:8080/', 'pop3://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T report.eml smtp://127.0.0.1:8080/shop.example.com
curl.exe -sS -o NUL --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "LIST 1" pop3://127.0.0.1:8081/
try { sh two-clients.sh 8081 } finally { Stop-Process $server0 }
